import argparse
import json
import sys

from tally import report as report_mod
from tally import store as store_mod
from tally.config import DEFAULT_CURRENCY
from tally.utils import month_key, parse_date

DEFAULT_STORE = "tally.json"


class UserError(Exception):
    """Raised for errors caused by invalid user input or bad environment."""


def _load(args):
    try:
        return store_mod.load(args.store)
    except json.JSONDecodeError as exc:
        raise UserError("store file is not valid JSON: {}".format(exc))
    except OSError as exc:
        raise UserError("cannot read store '{}': {}".format(args.store, exc))


def cmd_add(args):
    if args.amount <= 0:
        raise UserError("amount must be positive, got {!r}".format(args.amount))
    data = _load(args)
    try:
        date = parse_date(args.date).isoformat()
    except ValueError as exc:
        raise UserError(str(exc))
    try:
        record = store_mod.add_expense(
            data,
            date=date,
            amount=args.amount,
            currency=args.currency,
            category=args.category,
            note=args.note or "",
        )
    except ValueError as exc:
        raise UserError(str(exc))
    try:
        store_mod.save(args.store, data)
    except OSError as exc:
        raise UserError("cannot write store '{}': {}".format(args.store, exc))
    print(
        "added #{id}: {amount_usd:.2f} USD  {category}  {date}".format(**record)
    )
    return 0

